{
  "word": "苦待",
  "definition_simple": "残酷或刻薄地对待别人。",
  "definition_standard": "虐待；刻薄、严酷地对待。",
  "examples": [
    "继母经常苦待这个孤儿。",
    "他虽然受尽苦待，却依然保持着善良的品质。",
    "历史上的暴君往往苦待百姓，最终导致民不聊生。"
  ]
}

[
  {
    "target_word": "获胜",
    "definition_simple": "赢了比赛或竞争。",
    "definition_standard": "在竞赛、对抗或斗争中取得胜利。",
    "example_sentences": [
      "经过艰苦的比赛，我们终于获胜了。",
      "这场比赛谁能获胜还很难说。",
      "他们凭借出色的团队配合赢得了获胜。"
    ]
  }
]

{
  "definition_simple": "赢了，取得胜利",
  "definition_standard": "在竞赛、斗争或比赛中取得胜利或成功。",
  "pos": "v.",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "我们队获胜了！"
    },
    {
      "tier": "T2",
      "sentence": "经过努力，他们终于获胜。"
    },
    {
      "tier": "T3",
      "sentence": "这场比赛谁会获胜，现在还很难说。"
    },
    {
      "tier": "T4",
      "sentence": "客场作战的球队凭借顽强的斗志艰难获胜。"
    },
    {
      "tier": "T5",
      "sentence": "候选人在辩论赛中表现出色，从而在选战中获胜。"
    },
    {
      "tier": "T6",
      "sentence": "在瞬息万变的商战中，唯有精准决策方能最终获胜。"
    }
