  "primary_collocate": "比赛",
  "collocation_distractors": [
    {
      "word": "失败",
      "reason": "失败表示未取得成功，与获胜语义相反，不能作为直接搭配。"
    },
    {
      "word": "练习",
      "reason": "练习是准备阶段的活动，通常不直接与获胜构成动宾或主谓搭配。"
    },
    {
      "word": "观众",
      "reason": "观众是观看比赛的人，而获胜通常是参赛者的行为结果。"
    }
  ],
  "syn_ant_candidates": [
