      "word": "取胜",
      "type": "synonym"
    },
    {
      "word": "胜利",
      "type": "synonym"
    },
    {
      "word": "失败",
      "type": "antonym"
    },
    {
      "word": "落败",
      "type": "antonym"
    }
  ]
}

[
  {
    "word": "无量",
    "pinyin": "wú liàng",
    "definition_simple": "数量极多，无法计算。",
    "definition_standard": "形容数量极多或高,无法计算或估量。",
    "example_sentences": [
      "这片茫茫的沙漠真是前途无量吗？不对，是无边无际、不可估量。",
      "祝愿大家福寿无量，阖家幸福。",
      "宇宙空间无量无边，人类对它的探索永无止境。"
    ]
  }
]

{
  "definition_simple": "长时间地虐待、折磨或苛刻对待某人。",
  "definition_standard": "指长期给予痛苦的待遇，在精神或肉体上施加残酷、苛刻的虐待或折磨。",
  "pos": "verb",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "sentence": "地主常常苦待穷苦的长工。"
    },
    {
      "tier": "T2",
      "sentence": "继母总是苦待这个失去母亲的孩子。"
    },
    {
      "tier": "T3",
      "sentence": "在那个黑暗的时代，战俘们遭到了敌人无休止的苦待。"
    },
    {
      "tier": "T4",
      "sentence": "善良的仆人虽然屡遭苦待，却依然保持着忠诚与宽容。"
    },
    {
      "tier": "T5",
      "sentence": "历史不应忘记那些在流放期间遭受残酷苦待的革命志士。"
    },
    {
      "tier": "T6",
      "sentence": "面对命运的百般苦待，他非但没有消沉，反而淬炼出坚韧不拔的意志。"
    }
  ],
  "primary_collocate": "奴役",
  "collocation_distractors": [
    {
      "word": "优待",
      "reason": "优待表示给予优厚的好待遇，与苦待的虐待含义完全相反，无法构成习惯搭配。"
    },
    {
      "word": "款待",
      "reason": "款待侧重于热情诚恳地招待客人，常用于正面场景，而苦待带有贬义和残酷色彩。"
    },
    {
      "word": "看待",
      "reason": "看待是中性词，表示对事物或人的看法、态度，不能直接用来修饰或组合痛苦的待遇。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "虐待",
      "type": "synonym"
    },
    {
      "word": "折磨",
      "type": "synonym"
    },
    {
      "word": "善待",
      "type": "antonym"
    },
    {
      "word": "厚待",
      "type": "antonym"
    }
  ]
}

{
  "word": "获胜",
  "definition_simple": "赢得比赛或斗争",
  "definition_standard": "在竞赛、斗争或对抗中取得胜利",
  "pos": "v",
  "semantic_class": "action",
  "examples": [
    {
      "sentence": "我们获胜了。",
      "tier": "T1",
      "translation": "We won."
    },
    {
      "sentence": "这场比赛谁获胜了？",
      "tier": "T1",
      "translation": "Who won this match?"
    },
    {
      "sentence": "中国队在决赛中获胜。",
      "tier": "T2",
      "translation": "The Chinese team won the final."
    },
    {
      "sentence": "他们靠团队合作获胜。",
      "tier": "T2",
      "translation": "They won by teamwork."
    },
    {
      "sentence": "经过激烈的角逐，他终于获胜了。",
      "tier": "T3",
      "translation": "After fierce competition, he finally won."
    },
    {
      "sentence": "这场胜利使我们获得了继续前进的勇气，并在接下来的比赛中再次获胜。",
      "tier": "T4",
      "translation": "This victory gave us the courage to move forward and win again in the next match."
    },
    {
      "sentence": "想要在竞争激烈的市场中获胜，企业必须不断进行技术创新。",
      "tier": "T5",
      "translation": "To win in a highly competitive market, enterprises must continuously innovate in technology."
    },
    {
      "sentence": "辩论赛双方势均力敌，最终正方凭借严密的逻辑论证险胜获胜。",
      "tier": "T5",
      "translation": "The two sides of the debate were evenly matched, and ultimately the affirmative side narrowly won with rigorous logical arguments."
    },
    {
      "sentence": "纵观整场战役，战略上的先发制人是决定能否最终获胜的关键所在。",
      "tier": "T6",
      "translation": "Looking at the whole campaign, strategic preemption is the key to determining whether one can ultimately win."
    },
    {
      "sentence": "在博弈论的框架下，理性的参与者会寻求能够实现自身效用最大化并确保获胜的策略。",
      "tier": "T6",
      "translation": "Under the framework of game theory, rational participants will seek strategies that maximize their own utility and ensure victory."
    }
  ],
  "morphological_forms": [
    "获胜了",
    "获胜者"
  ],
  "primary_collocate": "比赛获胜",
  "word_family_forms": [
    "获胜者",
    "不获胜"
  ],
  "syn_ant_candidates": {
    "synonyms": [
      "赢",
      "胜利",
      "取胜",
      "得胜"
    ],
    "antonyms": [
      "失败",
      "战败",
      "落败",
      "输"
    ]
  }
}

{
  "word": "苦待",
  "pinyin": "kǔdài",
  "definition_simple": "To treat someone harshly or cruelly.",
  "definition_standard": "To treat with cruelty, harshness, or maltreatment; to oppress.",
  "pos": "v.",
  "semantic_class": "interpersonal action",
  "morphological_forms": [
    "苦待",
    "苦待着",
    "苦待过"
  ],
  "primary_collocate": "虐待",
  "word_family_forms": [
    "刻薄",
    "虐待",
    "优待"
  ],
  "syn_ant_candidates": {
    "synonyms": [
      "虐待",
      "折磨",
      "苛待"
    ],
    "antonyms": [
      "优待",
      "善待",
      "厚待"
    ]
  },
  "examples": [
    {
      "sentence": "雇主经常苦待底层的劳工。",
      "translation": "The employer often mistreats the lower-class laborers.",
      "tier": "T1"
    },
    {
      "sentence": "历史上的暴君总是苦待百姓。",
      "translation": "Tyrants in history always oppressed the common people.",
      "tier": "T2"
    },
    {
      "sentence": "她在这个家庭里长期受到继母的苦待。",
      "translation": "She suffered long-term mistreatment by her stepmother in this family.",
      "tier": "T3"
    },
    {
      "sentence": "法律严惩那些苦待孤儿寡母的行为。",
      "translation": "The law severely punishes acts of mistreating orphans and widows.",
      "tier": "T4"
    },
    {
      "sentence": "面对无理的苦待，他选择了用法律武器保护自己。",
      "translation": "Faced with unreasonable mistreatment, he chose to use legal weapons to protect himself.",
      "tier": "T5"
    },
    {
      "sentence": "那种系统性地苦待弱势群体的社会制度应当被彻底抛弃。",
      "translation": "That social system which systematically mistreats vulnerable groups should be utterly abandoned.",
      "tier": "T6"
    },
    {
      "sentence": "他们绝不容许任何人苦待动物。",
      "translation": "They by no means allow anyone to mistreat animals.",
      "tier": "T2"
    },
    {
      "sentence": "那场战争中战俘遭到了残酷的苦待。",
      "translation": "Prisoners of war suffered cruel mistreatment during that war.",
      "tier": "T3"
    },
    {
      "sentence": "有些虐心小说专门描写主角被周围人苦待的情节。",
      "translation": "Some angst-heavy novels specifically depict plots where the protagonist is mistreated by people around them.",
      "tier": "T4"
    },
    {
      "sentence": "在漫长的封建社会中，地主阶级无情地盘剥和苦待佃农。",
      "translation": "During the long feudal society, the landlord class ruthlessly exploited and mistreated tenant farmers.",
      "tier": "T5"
    }
  ]
}

{
  "morphology_wrong_forms": [
    {
      "wrong_form": "获胜着",
      "explanation": "Incorrectly uses the nominal suffix '着' (which is a progressive aspect marker) instead of '者' (person) to form 'winner'."
    },
    {
      "wrong_form": "被获胜",
      "explanation": "Treats the verb incorrectly as passive; '获胜' (to win) is an active intransitive/semi-transitive verb and rarely takes the passive '被'."
    },
    {
      "wrong_form": "获胜化",
      "explanation": "Incorrectly attaches the suffix '化' (to -ize/transform into) to an achievement verb where it makes no semantic sense."
    }
  ],
  "l1_audio_confusables": [
    {
      "word": "获生",
      "explanation": "Sounds nearly identical (huò shēng vs huò shèng, differing only in tone for the second syllable), but means to obtain life or survive."
    },
    {
      "word": "获盛",
      "explanation": "Homophonous in some dialects (huò shèng), but '盛' relates to prosperity or abundance, not victory in a competition."
    },
    {
      "word": "货肾",
      "explanation": "A phonetically similar nonsense combination (huò shèn) that sounds like a mispronounced version of '获胜'."
    }
  ],
  "collocation_distractors": [
    {
      "word": "天气",
      "explanation": "Weather cannot collocate directly as an object or direct modifier with the act of winning a competition."
    },
    {
      "word": "桌子",
      "explanation": "An inanimate noun 'table' that makes no semantic sense as a direct object of 'to win'."
    },
    {
      "word": "速度",
      "explanation": "Speed is a measurement, not an appropriate direct object for the verb '获胜' (you win a match/prize, not speed)."
    }
  ],
  "collocation_wrong_collocate": {
    "wrong_collocate": "赢得获胜",
    "explanation": "'赢得' (to win/gain) and '获胜' (to win/achieve victory) are semantic redundancies when placed together as verb-object."
  },
  "cloze_distractors": [
    {
      "option": "获得",
      "explanation": "Means 'to obtain', but usually requires an object like '奖品' (prize) or '成功' (success) rather than standing alone as an intransitive predicate like '获胜'."
    },
    {
      "option": "成功",
      "explanation": "Means 'to succeed'; while conceptually close, it does not fit the specific contest/match context that '获胜' implies."
    },
    {
      "option": "失败",
      "explanation": "The exact antonym (to fail/lose), used as a distractor for meaning comprehension."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "这场比赛非常获胜，大家都很高兴。",
      "reason": "Used '获胜' as a descriptive adjective modifying a noun/event, but it is an action verb."
    },
    {
      "sentence": "他为了获胜这个奖杯，付出了很多努力。",
      "reason": "Incorrectly treats '获胜' as a transitive verb taking a physical object like a trophy; should use '赢得' or '夺得'."
    },
    {
      "sentence": "老师获胜了我们班明天去春游。",
      "reason": "Nonsensical subject ('teacher') and object clause for '获胜', which requires a competitive context."
    }
  ],
  "spot_incorrect": {
    "sentence": "经过激烈的讨论，我们终于在辩论赛中获胜了冠军。",
    "planted_error": "获胜了冠军",
    "error_description": "'获胜' is an intransitive verb and cannot take a direct object like '冠军'.",
    "corrected_version": "经过激烈的讨论，我们终于在辩论赛中获得了冠军。"
  },
  "word_family_fake_forms": [
    "获败",
    "胜获",
    "得胜者化"
  ],
  "particle_candidates": [
    "在",
    "把",
    "被",
    "从"
  ]
}

{
  "word": "裁判",
  "definition_simple": "比赛中的裁判员，或者法院的法官和审判工作。",
  "definition_standard": "1. 体育比赛中公正判定胜负和规则执行的人员；2. 司法机关对案件的审判和判决。",
  "examples": [
    "这场足球比赛的裁判非常公正，赢得了双方球员的尊重。",
    "裁判吹响了比赛结束的哨音，比分定格在二比一。",
    "法院依法作出了公正的裁判，维护了受害者的合法权益。"
  ]
}

{
  "morphology_wrong_forms": [
    {
      "form": "苦待着",
      "explanation": "Adding the progressive aspect marker '着' incorrectly turns this stative or achievement verb into an ongoing action, which misrepresents its typical lexical aspect."
    },
    {
      "form": "苦待了",
      "explanation": "Attaching the perfective particle '了' implies a completed action of mistreatment, whereas the base form often describes an enduring state or habit of harsh treatment."
    },
    {
      "form": "苦待过",
      "explanation": "Using the experiential marker '过' frames the mistreatment as a past discrete life experience, altering the core valence of ongoing severity."
    }
  ],
  "l1_audio_confusables": [
    {
      "word": "枯代",
      "explanation": "Sounds phonetically similar (kū dài) but is a non-existent lexeme in standard Mandarin, often confused by learners mishearing the third tone on '苦'."
    },
    {
      "word": "库带",
      "explanation": "Sounds like kù dài, but means 'belt/strap' (裤带 variant), completely unrelated to the act of mistreatment."
    },
    {
      "word": "哭贷",
      "explanation": "Sounds like kū dài, combining 'to cry' and 'to loan', an unnatural pairing that sounds superficially like the target word."
    }
  ],
  "collocation_distractors": [
    {
      "word": "快乐",
      "explanation": "One does not 'bitterly-treat happiness'; '苦待' requires an object that can suffer abuse or neglect, not a positive abstract noun."
    },
    {
      "word": "风景",
      "explanation": "Scenery cannot be mistreated or subjected to harsh enduring neglect in standard Chinese collocations."
    },
    {
      "word": "真诚",
      "explanation": "Sincerity is an attribute or feeling, not an entity that can undergo the harsh mistreatment denoted by '苦待'."
    }
  ],
  "collocation_wrong_collocate": {
    "word": "奖励",
    "explanation": "奖励 (reward) is semantically opposite to the harsh, abusive nature of 苦待; one cannot '苦待奖励' (harshly mistreatment a reward)."
  },
  "cloze_distractors": [
    {
      "option": "对待",
      "explanation": "A common neutral alternative, but it lacks the severe, negative, and often oppressive nuance specifically carried by '苦待'."
    },
    {
      "option": "期待",
      "explanation": "Meaning 'to look forward to', it is chosen purely based on visual similarity ('待') but makes zero semantic sense in a context of hardship."
    },
    {
      "option": "虐待",
      "explanation": "While close in meaning (abuse), it refers more to physical or direct cruelty rather than the specific enduring, bitter treatment implied by '苦待'."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "老板每天都苦待员工，发了厚年终奖。",
      "reason": "Contradictory context: giving a generous year-end bonus clashes with the harsh mistreatment implied by '苦待'."
    },
    {
      "sentence": "为了减肥，她开始苦待自己的身体做瑜伽。",
      "reason": "Inappropriate usage: doing yoga is a healthy practice, whereas '苦待' implies severe, harmful maltreatment."
    },
    {
      "sentence": "这朵花需要苦待才能在温室里盛开。",
      "reason": "Semantic mismatch: flowers require care and nurturing, not harsh abuse or mistreatment."
    }
  ],
  "spot_incorrect": {
    "sentence": "经理对下属非常温和，总是苦待他们完成任务。",
    "planted_error": "苦待",
    "error_description": "The adjective '温和' (gentle/mild) contradicts the harsh and abusive nature of '苦待' (mistreat harshly).",
    "corrected_version": "经理对下属非常温和，总是鼓励他们完成任务。"
  },
  "word_family_fake_forms": [
    "苦性",
    "待苦",
    "反苦待"
  ],
  "particle_candidates": [
    "を",
    "に",
    "で",
    "が"
  ]
}

